mapper.select:
SELECT 
FROM deployment
WHERE id = #{id}
  AND deleted = 0
  AND EXISTS (
    SELECT 1
    FROM deployment_project dp
    JOIN project p ON p.id = dp.project_id
    WHERE dp.deployment_id = deployment.id
      AND (
        p.owner_id = #{ownerId}
        OR EXISTS (
          SELECT 1 FROM project_member pm
          WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
        )
      )
  )

SELECT 
FROM deployment
WHERE deleted = 0

    AND EXISTS (
      SELECT 1 FROM deployment_project dp
      WHERE dp.deployment_id = deployment.id
        AND dp.project_id = #{projectId}
    )


    AND EXISTS (
      SELECT 1
      FROM deployment_project dp
      JOIN project p ON p.id = dp.project_id
      WHERE dp.deployment_id = deployment.id
        AND (
          p.owner_id = #{ownerId}
          OR EXISTS (
            SELECT 1 FROM project_member pm
            WHERE pm.project_id = p.id AND pm.user_id = #{ownerId}
          )
        )
    )

ORDER BY created_at DESC, id DESC

SELECT deployment_id, project_id FROM deployment_project WHERE deployment_id IN
#{deploymentId}
ORDER BY deployment_id, project_id

SELECT COUNT(DISTINCT deployment.id)
FROM deployment
JOIN deployment_project dp ON dp.deployment_id = deployment.id
WHERE dp.project_id IN

    #{projectId}

  AND deployment.name = #{name}
  AND deleted = 0

    AND deployment.id != #{excludingId}

