INSERT INTO deployment (
    project_id, server_id, name, remote_directory,
    script_filename, script_content, script_hash, execution_mode, project_script_path,
    deleted, created_at, updated_at
) VALUES (
    #{projectId}, #{serverId}, #{name}, #{remoteDirectory},
    #{scriptFilename}, #{scriptContent}, #{scriptHash}, #{executionMode}, #{projectScriptPath},
    0, #{createdAt}, #{updatedAt}
)
